raw:
{
  "summary": [
    {
      "text": "Решение уравнения диффузии для давления сводится к интегралу вероятности.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Итоговая формула использует функцию эрфа (erf) от безразмерной координаты.",
      "claims": [
        "c2"
      ]
    }
  ],
  "how_it_works": [
    {
      "text": "Для решения исходного уравнения вводят замену переменной dP/du = ξ.",
      "claims": [
        "c3"
      ]
    },
    {
      "text": "Полученное уравнение для ξ имеет вид dξ/du + 2uξ = 0.",
      "claims": [
        "c4"
      ]
    },
    {
      "text": "Разделяют переменные: dξ/ξ = -2u du.",
      "claims": [
        "c5"
      ]
    },
    {
      "text": "Интегрирование дает ln ξ = -u² + ln C₁.",
      "claims": [
        "c6"
      ]
    },
    {
      "text": "Потенцирование приводит к выражению ξ = C₁ e^(-u²).",
      "claims": [
        "c7"
      ]
    },
    {
      "text": "Постоянная C₁ является константой интегрирования.",
      "claims": [
        "c8"
      ]
    },
    {
      "text": "Второе интегрирование с учетом граничного условия дает P = C₁ ∫₀ᵘ e^(-u²) du.",
      "claims": [
        "c9"
      ]
    },
    {
      "text": "Для нахождения C₁ верхний предел интеграла стремят к бесконечности.",
      "claims": [
        "c10"
      ]
    },
    {
      "text": "Используется известное значение интеграла ∫₀^∞ e^(-u²) du = √π/2.",
      "claims": [
        "c11"
      ]
    },
    {
      "text": "Отсюда следует, что C₁ = 2/√π.",
      "claims": [
        "c12"
      ]
    },
    {
      "text": "Окончательная формула для P содержит интеграл от 0 до x/(2√(κt)).",
      "claims": [
        "c13"
      ]
    },
    {
      "text": "Этот интеграл называется интегралом вероятности.",
      "claims": [
        "c14"
      ]
    },
    {
      "text": "Функция табулирована и изменяется в пределах от 0 до 1.",
      "claims": [
        "c15"
      ]
    },
    {
      "text": "Интеграл имеет специальное обозначение erf(x/(2√(κt))).",
      "claims": [
        "c16"
      ]
    },
    {
      "text": "Закон распределения давления записывается через функцию erf.",
      "claims": [
        "c17"
      ]
    }
  ],
  "steps": [
    {
      "text": "Вводят замену переменной ξ = dP/du.",
      "claims": [
        "c3"
      ]
    },
    {
      "text": "Решают полученное ОДУ методом разделения переменных.",
      "claims": [
        "c4",
        "c5"
      ]
    },
    {
      "text": "Находят общее решение ξ = C₁ e^(-u²).",
      "claims": [
        "c7"
      ]
    },
    {
      "text": "Интегрируют ξ по u, учитывая первое граничное условие.",
      "claims": [
        "c9"
      ]
    },
    {
      "text": "Определяют C₁, используя второе граничное условие и известный интеграл.",
      "claims": [
        "c10",
        "c11",
        "c12"
      ]
    },
    {
      "text": "Записывают итоговую формулу через функцию erf.",
      "claims": [
        "c13",
        "c16",
        "c17"
      ]
    }
  ],
  "examples": [],
  "numbers": [
    {
      "text": "Функция изменяется в пределах от 0 до 1.",
      "claims": [
        "c15"
      ]
    }
  ],
  "formulas": [
    {
      "unit": "u483-06",
      "latex": "\\frac{d\\xi}{du} + 2u\\xi = 0",
      "vars": [
        {
          "sym": "\\xi",
          "meaning": "производная dP/du",
          "unit": "-"
        },
        {
          "sym": "u",
          "meaning": "автомодельная переменная",
          "unit": "-"
        }
      ]
    },
    {
      "unit": "u483-12",
      "latex": "\\xi = \\frac{dP}{du} = C_1 e^{-u^2}",
      "vars": [
        {
          "sym": "C_1",
          "meaning": "постоянная интегрирования",
          "unit": "-"
        }
      ]
    },
    {
      "unit": "u484-03",
      "latex": "\\frac{2}{\\sqrt{\\pi}} \\int_0^{\\frac{x}{2\\sqrt{\\kappa t}}} e^{-u^2} du = \\operatorname{erf}\\left(\\frac{x}{2\\sqrt{\\kappa t}}\\right)",
      "vars": [
        {
          "sym": "x",
          "meaning": "координата",
          "unit": "м"
        },
        {
          "sym": "t",
          "meaning": "время",
          "unit": "с"
        },
        {
          "sym": "\\kappa",
          "meaning": "коэффициент пьезопроводности",
          "unit": "м²/с"
        }
      ]
    },
    {
      "unit": "u484-05",
      "latex": "p = p_{\\mathrm{r}} + (p_{\\mathrm{k}} - p_{\\mathrm{r}}) \\operatorname{erf}\\left(\\frac{x}{2\\sqrt{\\kappa t}}\\right)",
      "vars": [
        {
          "sym": "p",
          "meaning": "давление",
          "unit": "Па"
        },
        {
          "sym": "p_{\\mathrm{r}}",
          "meaning": "давление на границе",
          "unit": "Па"
        },
        {
          "sym": "p_{\\mathrm{k}}",
          "meaning": "начальное давление",
          "unit": "Па"
        }
      ]
    }
  ],
  "misconception": null,
  "data_meaning": {
    "input": "Координата x, время t, коэффициент пьезопроводности κ, граничные давления p_r и p_k.",
    "output": "Распределение давления p в точке x в момент времени t.",
    "breaks": [
      {
        "text": "Формула применима только для прямолинейно-параллельного потока упругой жидкости.",
        "claims": [
          "c17"
        ]
      }
    ],
    "hypotheses": []
  },
  "analogy": {
    "text": "Функция erf похожа на сигмоидную функцию в нейросетях, плавно переходящую от 0 к 1.",
    "breaks_where": "В отличие от сигмоида, аргумент erf здесь физически задан соотношением x/√t, а не обучаемыми весами."
  }}
